CREATE DATABASE IF NOT EXISTS news_social_analytics CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE news_social_analytics;
CREATE TABLE IF NOT EXISTS users(id BIGINT PRIMARY KEY AUTO_INCREMENT,full_name VARCHAR(120) NOT NULL,username VARCHAR(60) NOT NULL UNIQUE,email VARCHAR(190) NOT NULL UNIQUE,country VARCHAR(80),password_hash VARCHAR(100) NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'USER',email_verified BOOLEAN NOT NULL DEFAULT FALSE,account_enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) NOT NULL UNIQUE,description VARCHAR(255));
CREATE TABLE IF NOT EXISTS news_sources(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(160) NOT NULL UNIQUE,website_url VARCHAR(500),reliability_score DECIMAL(4,3));
CREATE TABLE IF NOT EXISTS news_articles(id BIGINT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(500) NOT NULL,description TEXT,content LONGTEXT,url VARCHAR(1000),author VARCHAR(160),source_name VARCHAR(160),category_name VARCHAR(80),published_at DATETIME,sentiment VARCHAR(20),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_news_published(published_at),INDEX idx_news_category(category_name));
CREATE TABLE IF NOT EXISTS social_posts(id BIGINT PRIMARY KEY AUTO_INCREMENT,platform VARCHAR(60) NOT NULL,author_name VARCHAR(160),post_text TEXT NOT NULL,post_url VARCHAR(1000),likes_count BIGINT NOT NULL DEFAULT 0,shares_count BIGINT NOT NULL DEFAULT 0,comments_count BIGINT NOT NULL DEFAULT 0,hashtag_text VARCHAR(500),sentiment VARCHAR(20),posted_at DATETIME,INDEX idx_social_posted(posted_at));
CREATE TABLE IF NOT EXISTS hashtags(id BIGINT PRIMARY KEY AUTO_INCREMENT,tag VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS post_hashtags(post_id BIGINT NOT NULL,hashtag_id BIGINT NOT NULL,PRIMARY KEY(post_id,hashtag_id),FOREIGN KEY(post_id) REFERENCES social_posts(id) ON DELETE CASCADE,FOREIGN KEY(hashtag_id) REFERENCES hashtags(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS bookmarks(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,article_id BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_bookmark(user_id,article_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(article_id) REFERENCES news_articles(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS search_history(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,query_text VARCHAR(1000) NOT NULL,result_count INT NOT NULL DEFAULT 0,searched_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_search_user_date(user_id,searched_at));
CREATE TABLE IF NOT EXISTS user_preferences(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL UNIQUE,theme VARCHAR(20) NOT NULL DEFAULT 'light',preferred_categories VARCHAR(1000),notifications_enabled BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS sentiment_results(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT,input_type VARCHAR(40) NOT NULL,input_reference VARCHAR(500),positive_score DECIMAL(7,4) NOT NULL DEFAULT 0,neutral_score DECIMAL(7,4) NOT NULL DEFAULT 0,negative_score DECIMAL(7,4) NOT NULL DEFAULT 0,label VARCHAR(20) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS trending_topics(id BIGINT PRIMARY KEY AUTO_INCREMENT,topic VARCHAR(250) NOT NULL,mention_count BIGINT NOT NULL DEFAULT 0,period_start DATETIME,period_end DATETIME,source_type VARCHAR(40),updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_trend_count(mention_count));
CREATE TABLE IF NOT EXISTS analysis_history(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,analysis_type VARCHAR(80) NOT NULL,input_preview VARCHAR(1000),result_json JSON,execution_ms BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_analysis_user_date(user_id,created_at));
CREATE TABLE IF NOT EXISTS algorithm_runs(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT,algorithm_name VARCHAR(100) NOT NULL,input_preview VARCHAR(1000),output_json JSON,execution_ms BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS notifications(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,title VARCHAR(250) NOT NULL,message VARCHAR(1000) NOT NULL,read_flag BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS citation_edges(id BIGINT PRIMARY KEY AUTO_INCREMENT,from_article_id BIGINT NOT NULL,to_article_id BIGINT NOT NULL,relationship_type VARCHAR(60) NOT NULL DEFAULT 'RELATED',weight DECIMAL(8,4) NOT NULL DEFAULT 1,UNIQUE KEY uq_edge(from_article_id,to_article_id,relationship_type),FOREIGN KEY(from_article_id) REFERENCES news_articles(id) ON DELETE CASCADE,FOREIGN KEY(to_article_id) REFERENCES news_articles(id) ON DELETE CASCADE);
